  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C11", "C30", "C113", "C88", "C78", "C116"],
  "contradictory_card_ids": ["C36"],
  "prediction_basis_card_ids": ["C11", "C30", "C113", "C88"],
  "claims": [
    {
      "claim": "The query is a close structural analog of cinacalcet (chiral secondary amine with a 3-arylpropyl chain); L3 human oral-exposure records for cinacalcet show measurable Cmax and AUC after single oral doses, e.g., Cmax 37.8 ng/mL and AUC0-t 254 ng·h/mL after 90 mg, and AUC0-inf 356 ng·h/mL after 100 mg.",
      "card_ids": ["C113", "C88", "C78"]
    },
    {
      "claim": "Ketoconazole co-administration increases cinacalcet AUCt from 254 to 517 ng·h/mL, indicating CYP3A4 first-pass metabolism, but this is not an absolute-bioavailability measurement and does not affirm F < 20%.",
      "card_ids": ["C105", "C88"]
    },
    {
      "claim": "The only direct human F measurement for a fasted-context analog remains propranolol at 27.2 ± 1.7%, above the 20% threshold.",
      "card_ids": ["C11", "C30"]
    },
    {
      "claim": "No L3 record provides an IV comparator or absolute F for cinacalcet or the query; absence of direct F is not evidence for low bioavailability.",
      "card_ids": ["C113", "C88", "C105"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C113", "C88", "C105", "C116", "C78"]
    }
  ],
  "evidence_gaps": [
    "No absolute oral bioavailability value is available for cinacalcet or the query; L3 AUC/Cmax records lack IV comparators.",
    "Query-specific first-pass metabolism and permeability are unmeasured; the cinacalcet ketoconazole interaction is indirect evidence.",
    "The query's very low neutral fraction (0.01) may limit passive permeability, but no measured absorption data are available.",
    "Most high-F L1/L2 records come from cirrhosis-modified conditions with reduced first-pass elimination, limiting transfer to healthy conditions."
  ],
  "decision_summary": "L3 oral exposure records for the close cinacalcet analog show measurable human AUC/Cmax and no affirmative sub-threshold F evidence. Combined with the direct human fasted propranolol F of 27.2%, the prediction remains high; confidence is moderate because no absolute F is available for the closest analog."
}

